package kr.blackwiki.smp;

import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.ItemStack;
import org.bukkit.persistence.PersistentDataType;
import java.util.*;
import java.util.logging.Level;

/** Main-thread transactions; escrow journal + receipts in the same .dat as coins/items.
 * Interrupted drafts, purchases, returns and payouts reconcile on the affected player's login.
 * A reserved listing stays invisible until the buyer's native data can be inspected. */
final class MarketService implements Listener {
    private final BlackWikiSMP p;
    final MarketLedger ledger;
    private final NamespacedKey receiptKey;
    private boolean fault;
    private record Draft(UUID token,int slot,ItemStack item,long price,long expires){}
    private final Map<UUID,Draft> drafts=new HashMap<>();
    private record Confirmation(UUID token,UUID listing,boolean cancel,long expires){}
    private final Map<UUID,Confirmation> confirmations=new HashMap<>();
    MarketService(BlackWikiSMP p)throws Exception{this.p=p;receiptKey=new NamespacedKey(p,"market-receipts");ledger=new MarketLedger(p.getDataFolder().toPath().resolve("market.yml"));for(var l:ledger.all())if(VaultService.decode(l.item())==null)throw new IllegalStateException("Empty escrow item "+l.id());}
    String status(){return fault?"저장 오류 · 거래 잠금":"판매 "+ledger.all().stream().filter(l->l.state()==MarketLedger.State.ACTIVE).count()+"개 · 미정산 "+ledger.all().stream().filter(l->l.state()==MarketLedger.State.SOLD).count()+"건";}
    boolean allowed(Player a){if(fault){p.tell(a,"유저상점 저장 오류로 거래가 잠겼습니다. 관리자에게 문의하세요.");return false;}return p.shop.allowed(a);}
    private Set<String> receipts(Player a){String s=a.getPersistentDataContainer().getOrDefault(receiptKey,PersistentDataType.STRING,"");return new LinkedHashSet<>(s.isEmpty()?List.of():Arrays.asList(s.split("\n")));}
    private boolean has(Player a,String kind,UUID id){return receipts(a).contains(kind+"/"+id);}
    private void receipt(Player a,String kind,UUID id){Set<String> set=receipts(a);set.add(kind+"/"+id);if(set.size()>1000)throw new IllegalStateException("Too many unresolved receipts");a.getPersistentDataContainer().set(receiptKey,PersistentDataType.STRING,String.join("\n",set));}
    private void clean(Player a){Set<String> set=receipts(a);boolean changed=set.removeIf(s->{try{String[] parts=s.split("/",2);var l=ledger.get(UUID.fromString(parts[1]));if(l==null)return true;return switch(parts[0]){case "escrow"->l.state()!=MarketLedger.State.DRAFT;case "buy"->l.state()!=MarketLedger.State.RESERVED;case "return"->l.state()!=MarketLedger.State.RETURNING;case "pay"->l.state()==MarketLedger.State.PAID;default->false;};}catch(Exception ex){return false;}});if(changed){a.getPersistentDataContainer().set(receiptKey,PersistentDataType.STRING,String.join("\n",set));p.vaults.saveAccount(a);}}
    private void fail(Player a,Exception ex){fault=true;p.tell(a,"유저상점 저장 오류입니다. 거래 기록을 보존했습니다. 관리자 확인 후 재시작하면 미완료 거래를 복구합니다.");p.getLogger().log(Level.SEVERE,"Market journal failure; new transactions locked, keep market.yml and player data together",ex);}
    @EventHandler(priority=EventPriority.LOW) public void join(PlayerJoinEvent e){reconcile(e.getPlayer());}
    @EventHandler public void quit(PlayerQuitEvent e){drafts.remove(e.getPlayer().getUniqueId());confirmations.remove(e.getPlayer().getUniqueId());}
    void reconcile(Player a){if(fault||p.backups!=null&&p.backups.running()||!p.vaults.healthy(a))return;try{
        for(var l:ledger.all()){
            if(l.seller().equals(a.getUniqueId())&&l.state()==MarketLedger.State.DRAFT)ledger.put(l.transition(has(a,"escrow",l.id())?MarketLedger.State.ACTIVE:MarketLedger.State.CANCELLED,null));
            else if(l.buyer()!=null&&l.buyer().equals(a.getUniqueId())&&l.state()==MarketLedger.State.RESERVED)ledger.put(l.transition(has(a,"buy",l.id())?MarketLedger.State.SOLD:MarketLedger.State.ACTIVE,l.buyer()));
            else if(l.seller().equals(a.getUniqueId())&&l.state()==MarketLedger.State.RETURNING)ledger.put(l.transition(has(a,"return",l.id())?MarketLedger.State.CANCELLED:MarketLedger.State.ACTIVE,null));
        }
        long total=0;for(var l:ledger.all())if(l.seller().equals(a.getUniqueId())&&l.state()==MarketLedger.State.SOLD){if(!has(a,"pay",l.id())){DataStore.User u=p.data.user(a);if(u.coins>Long.MAX_VALUE-l.price())continue;receipt(a,"pay",l.id());u.coins+=l.price();p.vaults.saveAccount(a);total=CoinClock.add(total,l.price());}ledger.put(l.transition(MarketLedger.State.PAID,l.buyer()));}
        clean(a);ledger.compact(p.cfg().getInt("market.completed-history",2000));if(total>0)p.tell(a,"유저상점 판매 대금 +"+VaultService.money(total)+"코인 (수수료 없음)");
        // The reconnecting buyer may have completed an interrupted purchase for an online seller.
        for(Player seller:Bukkit.getOnlinePlayers())if(seller!=a&&p.vaults.healthy(seller)&&ledger.all().stream().anyMatch(l->l.state()==MarketLedger.State.SOLD&&l.seller().equals(seller.getUniqueId())))payOnly(seller);
    }catch(Exception ex){fail(a,ex);}}
    private void payOnly(Player a)throws Exception{for(var l:ledger.all())if(l.state()==MarketLedger.State.SOLD&&l.seller().equals(a.getUniqueId())){if(!has(a,"pay",l.id())){var u=p.data.user(a);if(u.coins>Long.MAX_VALUE-l.price())continue;receipt(a,"pay",l.id());u.coins+=l.price();p.vaults.saveAccount(a);p.tell(a,"유저상점 판매 대금 +"+VaultService.money(l.price())+"코인");}ledger.put(l.transition(MarketLedger.State.PAID,l.buyer()));}clean(a);}
    private static String shortId(UUID id){return id.toString().substring(0,8);}
    private ItemStack preview(ItemStack original,String... lines){ItemStack copy=original.clone();var meta=copy.getItemMeta();List<Component> lore=meta.lore()==null?new ArrayList<>():new ArrayList<>(meta.lore());lore.add(Component.text("────────",NamedTextColor.DARK_GRAY));for(String s:lines)lore.add(Component.text(s,NamedTextColor.YELLOW));meta.lore(lore);copy.setItemMeta(meta);return copy;}
    void open(Player a,int page,boolean own){if(!allowed(a))return;List<MarketLedger.Listing> list=ledger.all().stream().filter(l->l.state()==MarketLedger.State.ACTIVE&&(!own||l.seller().equals(a.getUniqueId()))).sorted(Comparator.comparingLong(MarketLedger.Listing::created).reversed()).toList();page=Math.clamp(page,0,Math.max(0,(list.size()-1)/36));final int current=page;Gui.Menu m=p.gui.make(a,(own?"내 판매 목록":"유저상점")+" · "+(page+1));int start=page*36;for(int i=start;i<Math.min(start+36,list.size());i++){var l=list.get(i);int slot=9+i-start;m.inventory.setItem(slot,preview(VaultService.decode(l.item()),"판매자: "+p.data.name(l.seller()),"묶음 전체: "+VaultService.money(l.price())+"코인","번호: "+shortId(l.id()),l.seller().equals(a.getUniqueId())?"클릭: 판매 취소 확인":"클릭: 구매 확인"));m.actions.put(slot,b->confirm(b,l.id(),l.seller().equals(b.getUniqueId())));}
        p.gui.pages(m,page,list.size(),b->open(b,current-1,own),b->open(b,current+1,own));p.gui.button(m,46,Material.EMERALD,"손에 든 아이템 판매",b->sellGui(b,100),"가격은 손에 든 묶음 전체 기준","확인 전에는 아이템을 가져가지 않습니다.","/유저상점 등록 [가격]");p.gui.button(m,48,Material.CHEST,"내 판매 목록",b->open(b,0,true),"등록한 상품 취소·회수");p.gui.button(m,50,Material.GOLD_INGOT,"판매 대금 정산",b->{reconcile(b);open(b,current,own);},"오프라인 판매 대금은 접속 시 지급","/유저상점 정산");p.gui.button(m,52,Material.CLOCK,"전체 목록·새로고침",b->open(b,0,false));p.gui.show(a,m);
    }
    void sellGui(Player a,long price){if(!allowed(a))return;if(price<1||price>p.cfg().getLong("market.max-price",1000000000L))throw new IllegalArgumentException("가격은 1~"+VaultService.money(p.cfg().getLong("market.max-price",1000000000L))+"코인입니다.");ItemStack hand=a.getInventory().getItemInMainHand();if(hand.getType().isAir()||hand.getAmount()<1||hand.getAmount()>hand.getMaxStackSize()){p.tell(a,"판매할 정상적인 아이템 묶음을 주 손에 드세요.");return;}drawDraft(a,new Draft(UUID.randomUUID(),a.getInventory().getHeldItemSlot(),hand.clone(),price,System.currentTimeMillis()+120000));}
    private void drawDraft(Player a,Draft draft){drafts.put(a.getUniqueId(),draft);Gui.Menu m=p.gui.make(a,"유저상점 · 판매 가격 설정");m.inventory.setItem(4,preview(draft.item,"묶음 수량: "+draft.item.getAmount(),"묶음 전체를 이 가격에 판매합니다."));m.inventory.setItem(13,Gui.item(Material.GOLD_INGOT,"가격: "+VaultService.money(draft.price)+"코인","수수료 없음 · 판매 후 코인 지급","/유저상점 등록 숫자 로 직접 입력 가능"));long[] steps={1,10,100,1000,10000};for(int i=0;i<steps.length;i++){long step=steps[i];p.gui.button(m,19+i,Material.RED_WOOL,"-"+VaultService.money(step),b->adjust(b,draft,-step));p.gui.button(m,28+i,Material.LIME_WOOL,"+"+VaultService.money(step),b->adjust(b,draft,step));}p.gui.button(m,40,Material.LIME_CONCRETE,"확인 · 판매 등록",b->register(b,draft));p.gui.button(m,44,Material.RED_CONCRETE,"취소",b->{drafts.remove(b.getUniqueId());open(b,0,false);});p.gui.show(a,m);}
    private void adjust(Player a,Draft expected,long diff){if(drafts.get(a.getUniqueId())!=expected||expected.expires<System.currentTimeMillis()){p.tell(a,"가격 설정 시간이 만료되었습니다.");return;}drawDraft(a,new Draft(UUID.randomUUID(),expected.slot,expected.item,Math.clamp(expected.price+diff,1,p.cfg().getLong("market.max-price",1000000000L)),expected.expires));}
    private void register(Player a,Draft d){if(drafts.get(a.getUniqueId())!=d||d.expires<System.currentTimeMillis())return;drafts.remove(a.getUniqueId());if(!allowed(a))return;if(d.price<1||d.price>p.cfg().getLong("market.max-price",1000000000L)){p.tell(a,"가격 설정이 변경되었습니다. 다시 등록하세요.");return;}if(a.getInventory().getHeldItemSlot()!=d.slot||!a.getInventory().getItemInMainHand().equals(d.item)){p.tell(a,"손에 든 아이템이 변경되어 등록을 취소했습니다.");return;}
        long owned=ledger.all().stream().filter(l->!l.finished()&&l.seller().equals(a.getUniqueId())).count(),total=ledger.all().stream().filter(l->!l.finished()).count();if(owned>=p.cfg().getInt("market.max-listings-per-player",20)||total>=p.cfg().getInt("market.max-active-listings",2000)){p.tell(a,"판매 등록 한도에 도달했습니다.");return;}
        String encoded=VaultService.encode(d.item);if(encoded.length()>262144){p.tell(a,"아이템 데이터가 너무 커서 등록할 수 없습니다.");return;}var l=new MarketLedger.Listing(UUID.randomUUID(),a.getUniqueId(),null,d.price,encoded,MarketLedger.State.DRAFT,System.currentTimeMillis());try{ledger.put(l);receipt(a,"escrow",l.id());a.getInventory().setItem(d.slot,null);p.vaults.saveAccount(a);ledger.put(l.transition(MarketLedger.State.ACTIVE,null));clean(a);p.tell(a,"판매 등록 완료 #"+shortId(l.id())+" · "+d.item.getAmount()+"개 묶음 / "+VaultService.money(d.price)+"코인");open(a,0,true);}catch(Exception ex){fail(a,ex);}}
    void confirm(Player a,UUID id,boolean cancel){if(!allowed(a))return;var l=ledger.get(id);if(l==null||l.state()!=MarketLedger.State.ACTIVE){p.tell(a,"이미 판매되었거나 취소된 상품입니다.");return;}if(cancel!=l.seller().equals(a.getUniqueId())){p.tell(a,cancel?"본인의 상품만 취소할 수 있습니다.":"자신의 상품은 구매할 수 없습니다.");return;}Confirmation c=new Confirmation(UUID.randomUUID(),id,cancel,System.currentTimeMillis()+30000);confirmations.put(a.getUniqueId(),c);Gui.Menu m=p.gui.make(a,cancel?"판매 취소 확인":"유저상점 구매 확인");m.inventory.setItem(13,preview(VaultService.decode(l.item()),"판매자: "+p.data.name(l.seller()),"전체 가격: "+VaultService.money(l.price())+"코인",cancel?"취소 시 아이템을 인벤토리로 회수":"확인하면 코인 차감 후 아이템 지급"));p.gui.button(m,20,Material.LIME_CONCRETE,"확인",b->{Confirmation active=confirmations.remove(b.getUniqueId());if(active!=c||c.expires<System.currentTimeMillis())return;if(c.cancel)cancel(b,c.listing);else buy(b,c.listing);if(!fault)open(b,0,false);});p.gui.button(m,24,Material.RED_CONCRETE,"돌아가기",b->{confirmations.remove(b.getUniqueId());open(b,0,false);});p.gui.show(a,m);}
    boolean buy(Player a,UUID id){if(!allowed(a))return false;var l=ledger.get(id);if(l==null||l.state()!=MarketLedger.State.ACTIVE||l.seller().equals(a.getUniqueId())){p.tell(a,"구매할 수 없는 상품입니다.");return false;}var u=p.data.user(a);if(u.coins<l.price()){p.tell(a,"코인이 부족합니다.");return false;}ItemStack[] next=InventoryPlan.add(a.getInventory().getStorageContents(),List.of(VaultService.decode(l.item())));if(next==null){p.tell(a,"인벤토리에 상품을 받을 공간이 없습니다.");return false;}try{l=l.transition(MarketLedger.State.RESERVED,a.getUniqueId());ledger.put(l);receipt(a,"buy",id);u.coins-=l.price();a.getInventory().setStorageContents(next);p.vaults.saveAccount(a);ledger.put(l.transition(MarketLedger.State.SOLD,a.getUniqueId()));clean(a);Player seller=Bukkit.getPlayer(l.seller());if(seller!=null&&p.vaults.healthy(seller))payOnly(seller);p.tell(a,"구매 완료 -"+VaultService.money(l.price())+"코인");return true;}catch(Exception ex){fail(a,ex);return false;}}
    boolean cancel(Player a,UUID id){if(!allowed(a))return false;var l=ledger.get(id);if(l==null||l.state()!=MarketLedger.State.ACTIVE||!l.seller().equals(a.getUniqueId()))return false;ItemStack[] next=InventoryPlan.add(a.getInventory().getStorageContents(),List.of(VaultService.decode(l.item())));if(next==null){p.tell(a,"인벤토리가 가득 차서 판매를 취소하지 않았습니다.");return false;}try{l=l.transition(MarketLedger.State.RETURNING,null);ledger.put(l);receipt(a,"return",id);a.getInventory().setStorageContents(next);p.vaults.saveAccount(a);ledger.put(l.transition(MarketLedger.State.CANCELLED,null));clean(a);p.tell(a,"판매를 취소하고 아이템을 회수했습니다.");return true;}catch(Exception ex){fail(a,ex);return false;}}
    private UUID resolve(String text){List<UUID> matches=ledger.all().stream().map(MarketLedger.Listing::id).filter(id->id.toString().equalsIgnoreCase(text)||shortId(id).equalsIgnoreCase(text)).toList();if(matches.size()!=1)throw new IllegalArgumentException("상품 번호가 없거나 중복됩니다. 목록에서 선택하세요.");return matches.getFirst();}
    void command(Player a,String[] args){if(args.length==0){open(a,0,false);return;}switch(args[0]){case "등록","sell"->{if(args.length>2)throw new IllegalArgumentException("/유저상점 등록 [가격]");sellGui(a,args.length==2?Long.parseLong(args[1]):100);}case "내목록","mine"->open(a,0,true);case "목록","list"->open(a,0,false);case "정산","collect"->{reconcile(a);open(a,0,true);}case "구매","buy","취소","cancel"->{if(args.length!=2)throw new IllegalArgumentException("/유저상점 구매|취소 상품번호");confirm(a,resolve(args[1]),args[0].equals("취소")||args[0].equals("cancel"));}default->throw new IllegalArgumentException("/유저상점 [등록 [가격]|내목록|구매 번호|취소 번호|정산]");}}
}
